// ===================== HIGH-OUTPUT ACTIVE BUZZER DRIVER ===================
// Solid DC drive delivers full rated 85 dB acoustic volume from active piezo element.
// Non-blocking timer prevents CPU delay during control loop & SSE streaming.
#define BUZZER_IS_ACTIVE 1

static unsigned long buzzer_off_ms = 0;

void triggerBuzzer(int durationMs, int freqHz = 2400)
{
  if (buzzer_muted || durationMs <= 0) return;
#if BUZZER_IS_ACTIVE
  // Solid DC drive for Active Piezo Buzzer: maximum rated acoustic volume (85 dB)
  digitalWrite(PIN_BUZZER, HIGH);
  buzzer_off_ms = millis() + durationMs;
#else
  // Resonant square-wave drive for Passive Piezo Buzzer
  long halfPeriodUs = 1000000L / (freqHz * 2);
  long cycles = (long)freqHz * durationMs / 1000L;
  for (long i = 0; i < cycles; i++)
  {
    digitalWrite(PIN_BUZZER, HIGH);
    delayMicroseconds(halfPeriodUs);
    digitalWrite(PIN_BUZZER, LOW);
    delayMicroseconds(halfPeriodUs);
  }
#endif
}

void playTone(int freqHz, int durationMs)
{
  triggerBuzzer(durationMs, freqHz);
}

// --------------------- 4x Analog Oversampling & Median Filters ------------
static int avgAnalog(int pin)
{
  int sum = 0;
  for (int i = 0; i < 4; i++)
    sum += analogRead(pin);
  return sum / 4; // 4x oversampling halves ADC noise on MQ and LDR channels
}

// Dedicated Sensor Channel Resolvers (US1 GPIO 5/18 fixed; US2 GPIO 19/23 servo-mounted)
inline float getServoDist() { return (servo_us_channel == 1) ? dist1_cm : dist2_cm; }
inline float getBaseDist()  { return (servo_us_channel == 1) ? dist2_cm : dist1_cm; }

// --------------------- Helper: Ultrasonic Read with Timeout ---------------
struct UltrasonicReading { float cm; uint32_t pulse_us; uint8_t diagnostic; };
UltrasonicReading readUltrasonicCM(int trigPin, int echoPin, unsigned long timeoutUs = 22000)
{
  digitalWrite(trigPin, LOW);
  delayMicroseconds(4);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH, timeoutUs);
  if (duration <= 0 || duration > (long)timeoutUs)
    return {999.0f, 0, 0}; // Distinct sentinel; 120 cm is a valid measurement
  float cm = (duration * 0.0343f) / 2.0f;
  if (cm < ULTRASONIC_MIN_RELIABLE_CM) return {cm, (uint32_t)duration, 2};
  if (cm > ULTRASONIC_MAX_RELIABLE_CM) return {cm, (uint32_t)duration, 3};
  return {cm, (uint32_t)duration, 1};
}

// --------------------- Helper: Read MPU-6050 Motion & Vibration -----------
static int16_t readInt16BE()
{
  uint8_t hi = (uint8_t)Wire.read();
  uint8_t lo = (uint8_t)Wire.read();
  return (int16_t)((hi << 8) | lo);
}

// --------------------- Helper: Read MPU-6050 Motion & Attitude ------------
// Direct gravity vector decomposition with resting auto-tare & EMA noise filter.
// ZERO gyro drift: guaranteed 0.0° when board rests flat on desk or breadboard.
static float roll_bias = 0.0f, pitch_bias = 0.0f;
static int tare_samples = 0;
static float raw_roll_latest = 0.0f, raw_pitch_latest = 0.0f;

void tareMPU()
{
  roll_bias = raw_roll_latest;
  pitch_bias = raw_pitch_latest;
  roll_deg = 0.0f;
  pitch_deg = 0.0f;
  tare_samples = 50; // Lock tare
}

void readMPUMotion()
{
  if (!mpu_found)
  {
    vib_g = 0.02f;
    roll_deg = 0.0f;
    pitch_deg = 0.0f;
    return;
  }
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x3B);
  if (Wire.endTransmission(false) != 0)
    return;
  Wire.requestFrom((uint8_t)MPU_ADDR, (size_t)6, (bool)true);
  if (Wire.available() < 6)
    return;

  int16_t ax = readInt16BE();
  int16_t ay = readInt16BE();
  int16_t az = readInt16BE();

  float gx = ax / 16384.0f;
  float gy = ay / 16384.0f;
  float gz = az / 16384.0f;

  float total_g = sqrtf(gx * gx + gy * gy + gz * gz);
  vib_g = fabsf(total_g - 1.0f);

  // Exact trigonometric tilt from gravity vector
  float raw_roll = atan2f(gy, gz) * 180.0f / PI;
  float raw_pitch = atan2f(-gx, sqrtf(gy * gy + gz * gz)) * 180.0f / PI;
  raw_roll_latest = raw_roll;
  raw_pitch_latest = raw_pitch;

  // Auto-tare initial resting tilt during first 30 samples after boot
  if (tare_samples < 30)
  {
    tare_samples++;
    roll_bias += (raw_roll - roll_bias) * 0.2f;
    pitch_bias += (raw_pitch - pitch_bias) * 0.2f;
    roll_deg = 0.0f;
    pitch_deg = 0.0f;
  }
  else
  {
    float unadjusted_roll = raw_roll - roll_bias;
    float unadjusted_pitch = raw_pitch - pitch_bias;

    // Smooth EMA low-pass filtering: removes bench vibration noise while tracking tilt in 3D
    roll_deg = 0.85f * roll_deg + 0.15f * unadjusted_roll;
    pitch_deg = 0.85f * pitch_deg + 0.15f * unadjusted_pitch;

    // Strict zero-tilt deadband when resting flat on desk (<0.9 deg bench vibration noise)
    if (fabsf(roll_deg) < 0.9f) roll_deg = 0.0f;
    if (fabsf(pitch_deg) < 0.9f) pitch_deg = 0.0f;
  }
}

// Forward Declaration for OLED
void updateOLEDDisplay();

// --------------------- Hardware Button Check (Multi-Pin Foolproof) --------
void checkHardwareButtons()
{
  if (millis() < 1500)
    return;

  uint32_t now = millis();
  int b0 = digitalRead(PIN_BTN_BOOT); // Onboard ESP32 BOOT button (active LOW)
  int b2 = digitalRead(PIN_BTN_EXT);  // Breadboard GPIO 2
  int b39 = digitalRead(PIN_BTN_SVN); // Header SVN GPIO 39

  if (baseline_btn2 == -1)
  {
    baseline_btn2 = b2;
    prev_btn2 = b2;
  }
  if (baseline_btn39 == -1)
  {
    baseline_btn39 = b39;
    prev_btn39 = b39;
  }

  bool pressed = false;

  if (b0 == LOW && prev_btn0 == HIGH)
    pressed = true;
  if (b2 != baseline_btn2 && prev_btn2 == baseline_btn2)
    pressed = true;
  if (b39 != baseline_btn39 && prev_btn39 == baseline_btn39)
    pressed = true;

  prev_btn0 = b0;
  prev_btn2 = b2;
  prev_btn39 = b39;

  if (pressed && (now - lastBtnPressMs > 250))
  {
    lastBtnPressMs = now;
    control_mode = (control_mode + 1) % 6;
    playTone(600 + control_mode * 150, 45); // Audible pitch per mode
    updateOLEDDisplay();                    // Immediate screen update
    Serial.printf("[CMD_ACK] BUTTON_PRESSED_MODE: %d\n", control_mode);
  }
}

// --------------------- Command Processor (Web Serial & HTTP) --------------
void processWebCommand(String cmd)
{
  cmd.trim();
  if (cmd.length() == 0 || cmd.length() > 96)
    return;

  if (cmd == "RESET")
  {
    web_manual_override = false;
    tareMPU();
    control_mode = 0; // Back to All Sensors HUD
    man_servo = -1;
    boost_temp = 0.0f;
    boost_vib = 0.0f;
    boost_gas = 0;
    boost_ldr = 0;
    radar1_until = 0;
    tripwire_until = 0;
    fault_drift_injected = false;
    test_start_ms = 0;
    track_state = TRACK_SEARCHING;
    track_sample_mask = track_target_mask = 0;
    track_broad_return = false;
    Serial.println("[CMD_ACK] RESET_ALL");
    updateOLEDDisplay();
  }
  else if (cmd.startsWith("MODE:"))
  {
    const int requested_mode = constrain(cmd.substring(5).toInt(), 0, 5);
    if (requested_mode == 1 && servo_us_channel != 2)
    {
      Serial.println("[CMD_REJECTED] MODE 1 requires servo-mounted US2 (SERVO_US:2)");
      return;
    }
    control_mode = requested_mode;
    step_active = false;
    man_servo = -1;
    if (control_mode == 1)
    {
      track_state = TRACK_SEARCHING;
      track_sweep_angle = 35.0f;
      track_sweep_dir = 1.0f;
      track_best_cm = 150.0f;
      track_best_angle = (float)servo_angle;
      track_sample_mask = track_target_mask = 0;
      track_broad_return = false;
      track_next_sample_ms = 0;
    }
    playTone(700 + control_mode * 120, 40);
    updateOLEDDisplay();
    Serial.printf("[CMD_ACK] SWITCHED_TO_MODE: %d\n", control_mode);
  }
  else if (cmd.startsWith("SERVO_US:"))
  {
    int ch = cmd.substring(9).toInt();
    if (ch == 1 || ch == 2)
    {
      if (control_mode == 1 && ch != 2)
      {
        Serial.println("[CMD_REJECTED] MODE 1 requires servo-mounted US2");
        return;
      }
      servo_us_channel = ch;
      Serial.printf("[CMD_ACK] SERVO_US_CHANNEL: %d\n", servo_us_channel);
    }
  }
  else if (cmd.startsWith("SERVO:"))
  {
    String val = cmd.substring(6);
    if (val == "AUTO")
      man_servo = -1;
    else
      man_servo = constrain(val.toInt(), 0, 180);

    if (man_servo < 0)
      Serial.println("[CMD_ACK] SERVO_AUTO");
    else
      Serial.printf("[CMD_ACK] SERVO_ANGLE: %d\n", man_servo);
  }
  else if (cmd.startsWith("SCENARIO:"))
  {
    String sc = cmd.substring(9);
    if (sc == "thermal")
      boost_temp = 8.5f;
    else if (sc == "gas")
      boost_gas = 2800;
    else if (sc == "flame")
      boost_ldr = -2000;
    else if (sc == "vibration")
      boost_vib = 0.85f;
    else if (sc == "radar1")
      radar1_until = millis() + 4500;
    else if (sc == "radar2")
      tripwire_until = millis() + 4500;
    else if (sc == "drift")
    {
      fault_drift_injected = !fault_drift_injected;
      if (!fault_drift_injected)
        cusum_twin.reset();
    }
    Serial.printf("[CMD_ACK] SCENARIO: %s (Drift=%d)\n", sc.c_str(), fault_drift_injected);
  }
  else if (cmd.startsWith("SLIDERS:"))
  {
    int p1 = cmd.indexOf(',', 8);
    int p2 = cmd.indexOf(',', p1 + 1);
    int p3 = cmd.indexOf(',', p2 + 1);
    int p4 = cmd.indexOf(',', p3 + 1);
    int p5 = cmd.indexOf(',', p4 + 1);
    if (p1 > 0 && p2 > 0 && p3 > 0 && p4 > 0 && p5 > 0)
    {
      web_manual_override = (cmd.substring(8, p1).toInt() == 1);
      man_temp = cmd.substring(p1 + 1, p2).toFloat();
      man_gas = cmd.substring(p2 + 1, p3).toInt();
      man_ldr = cmd.substring(p3 + 1, p4).toInt();
      man_vib = cmd.substring(p4 + 1, p5).toFloat();
      man_dist1 = cmd.substring(p5 + 1).toFloat();
      Serial.println("[CMD_ACK] SLIDERS_SYNCED");
    }
  }
  else if (cmd == "TARE_IMU" || cmd == "CALIBRATE_IMU" || cmd == "TARE")
  {
    tareMPU();
    Serial.println("[CMD_ACK] TARE_IMU_SUCCESS");
  }
  else if (cmd == "TEST_ALARM")
  {
    // Non-blocking alarm sequence: keeps control loop, WDT, and telemetry active
    test_start_ms = millis() | 1;
    playTone(880, 40); // Soft, non-screeching test chirp
    Serial.println("[CMD_ACK] TEST_ALARM_STARTED");
  }
  else if (cmd == "MUTE_BUZZER" || cmd == "MUTE_SOUND" || cmd == "SOUND:0")
  {
    buzzer_muted = true;
    digitalWrite(PIN_BUZZER, LOW);
    Serial.println("[CMD_ACK] BUZZER_MUTED");
  }
  else if (cmd == "UNMUTE_BUZZER" || cmd == "UNMUTE_SOUND" || cmd == "SOUND:1")
  {
    buzzer_muted = false;
    Serial.println("[CMD_ACK] BUZZER_UNMUTED");
  }
  else if (cmd == "PROX_MUTE")
  {
    // Silence only the yellow caution beep. Never mask the alarm LEDs/state.
    prox_alarm_muted = true;
    Serial.println("[CMD_ACK] PROX_CAUTION_BEEP_MUTED");
  }
  else if (cmd == "PROX_UNMUTE")
  {
    prox_alarm_muted = false;
    Serial.println("[CMD_ACK] PROX_UNMUTED");
  }
  else if (cmd == "RESET_ALARM")
  {
    // Reset the software-model detector only; live hazards are recomputed.
    cusum_twin.reset();
    fault_drift_injected = false;
    Serial.println("[CMD_ACK] MODEL_DETECTOR_RESET; LIVE ALARMS UNCHANGED");
  }
}

// --------------------- Real-Time Step Response Metrics (Mode 4) -----------
static void finishStepMeasure()
{
  if (!step_active || step_t90 < 0.0f)
  {
    step_active = false;
    return;
  }
  meas_tr_ms = (step_t90 - step_t10) * 1000.0f;
  meas_ts_ms = step_last_out * 1000.0f;
  meas_os_pct = max(0.0f, (step_peak - 1.0f) * 100.0f);
  meas_sse_pct = fabsf((x1_real - step_from) / (step_to - step_from) - 1.0f) * 100.0f;
  step_valid = true;
  step_active = false;
}

static void beginStepMeasure(float from, float to)
{
  finishStepMeasure();
  step_from = from;
  step_to = to;
  step_elapsed = 0.0f;
  step_t10 = step_t90 = -1.0f;
  step_last_out = 0.0f;
  step_peak = 0.0f;
  step_active = (fabsf(to - from) > 0.2f);
}

static void updateStepMeasure(float h)
{
  if (!step_active)
    return;
  step_elapsed += h;
  float frac = (x1_real - step_from) / (step_to - step_from);
  if (step_t10 < 0.0f && frac >= 0.1f)
    step_t10 = step_elapsed;
  if (step_t90 < 0.0f && frac >= 0.9f)
    step_t90 = step_elapsed;
  if (frac > step_peak)
    step_peak = frac;
  if (fabsf(frac - 1.0f) > 0.02f)
    step_last_out = step_elapsed; // Last instant outside 2% band
}

static void recoverIfNonFinite(float setpoint_r)
{
  if (isfinite(x1_real) && isfinite(x2_real) && isfinite(x1_hat) && isfinite(x2_hat) && isfinite(y_twin))
    return;
  x1_real = x1_hat = y_twin = x1_t = setpoint_r;
  x2_t = 0.0f;
  x2_real = x2_hat = 0.0f;
  peak_x2_hat = 0.0f;
  cusum_twin.reset();
  Serial.println("[WARN] non-finite state detected, estimator re-seeded");
}

// --------------------- Discrete State-Space & Observer Engine -------------
void stepControlAndObserver(float setpoint_r, float dt)
{
  dt = constrain(dt, 0.001f, 0.2f);
  const int steps = max(1, (int)lroundf(dt * 1000.0f));
  const float h = 0.001f; // exact-ZOH propagation substep (gains::Af / gains::Bf are for 1 ms)

  // Sample instant: measure -> correct observer -> dlqr control law (MATLAB Section 8)
  const float mech_disturbance = (vib_g > 0.20f) ? (vib_g * 0.25f) : 0.0f;
  const float drift_offset = fault_drift_injected ? 0.145f : 0.0f;
  const float y_measured = constrain(x1_real + mech_disturbance + drift_offset, 0.0f, 1.5f);

  const float innov = y_measured - x1_hat;
  x1_hat += gains::L[0] * innov;
  x2_hat += gains::L[1] * innov;

  control_u = gnc::saturatedLqr(gains::Nbar, gains::K[0], gains::K[1], setpoint_r, x1_hat, x2_hat);
  residual = fabsf(y_measured - x1_t); // r(t) = |y_phys - y_twin| (Araujo et al. 2025)

  // Propagate plant, digital twin and observer with exact discrete model
  for (int i = 0; i < steps; i++)
  {
    float n1 = gains::Af[0][0] * x1_real + gains::Af[0][1] * x2_real + gains::Bf[0] * control_u;
    float n2 = gains::Af[1][0] * x1_real + gains::Af[1][1] * x2_real + gains::Bf[1] * control_u;
    x1_real = n1;
    x2_real = n2;
    updateStepMeasure(h);

    float t1 = gains::Af[0][0] * x1_t + gains::Af[0][1] * x2_t + gains::Bf[0] * control_u;
    float t2 = gains::Af[1][0] * x1_t + gains::Af[1][1] * x2_t + gains::Bf[1] * control_u;
    x1_t = t1;
    x2_t = t2;

    float o1 = gains::Af[0][0] * x1_hat + gains::Af[0][1] * x2_hat + gains::Bf[0] * control_u;
    float o2 = gains::Af[1][0] * x1_hat + gains::Af[1][1] * x2_hat + gains::Bf[1] * control_u;
    x1_hat = o1;
    x2_hat = o2;

    if (fabsf(x2_hat) > fabsf(peak_x2_hat))
      peak_x2_hat = x2_hat;
  }
  y_twin = x1_t;
  recoverIfNonFinite(setpoint_r);

  if (control_mode == 1)
  {
    // Mode 1 is a single-range-sensor sector scan/hold, not 2-D hand tracking.
    // The measured/commanded sector is reported separately from model state.
    x1_real = setpoint_r;
    x1_hat = setpoint_r;
    x1_t = setpoint_r;
    x2_real = 0.0f;
    x2_hat = 0.0f;
    peak_x2_hat = 0.0f;
  }

  // CUSUM sequential test: ONCE per control tick (20 Hz)
  if (control_mode == 3 || fault_drift_injected)
    cusum_twin.update(x1_real + drift_offset, y_twin);
  else
    cusum_twin.reset();

  servo_angle = (int)constrain(x1_real * 180.0f, 0.0f, 180.0f);
  damperServo.write(servo_angle);
}

// --------------------- Telemetry JSON Packet Builder ----------------------
static String fnum(float v, int digits)
{
  return isfinite(v) ? String(v, digits) : String("null");
}

static String jsonEscape(const String &in)
{
  String out;
  for (unsigned i = 0; i < in.length(); i++)
  {
    char c = in[i];
    if (c == '"' || c == '\\')
      out += '\\';
    if (c >= 0x20)
      out += c;
  }
  return out;
}

String getTelemetryJSON()
{
  String json;
  json.reserve(1100);
  json = "{";
  json += "\"source\":\"ESP32_FIRMWARE\",\"manualOverride\":" + String(web_manual_override ? 1 : 0) + ",";
  json += "\"mpuOk\":" + String(mpu_found ? 1 : 0) + ",\"oledOk\":" + String(oled_found ? 1 : 0) + ",\"dhtOk\":" + String(dht_ok ? 1 : 0) + ",";
  json += "\"us1EchoOk\":" + String(us1_echo_ok ? 1 : 0) + ",\"us2EchoOk\":" + String(us2_echo_ok ? 1 : 0) + ",";
  json += "\"us1AgeMs\":" + String(us1_seen_valid ? millis() - us1_last_valid_ms : 4294967295UL) + ",";
  json += "\"us2AgeMs\":" + String(us2_seen_valid ? millis() - us2_last_valid_ms : 4294967295UL) + ",";
  json += "\"us1PulseUs\":" + String(us1_pulse_us) + ",\"us2PulseUs\":" + String(us2_pulse_us) + ",";
  json += "\"us1Diagnostic\":" + String(us1_diag) + ",\"us2Diagnostic\":" + String(us2_diag) + ",";
  json += "\"ldrRaw\":" + String(ldr_raw) + ",\"ldrCalibrated\":0,";
  json += "\"temp\":" + fnum(temp_c, 2) + ",";
  json += "\"hum\":" + fnum(humidity, 1) + ",";
  json += "\"dT\":" + fnum(temp_rate, 3) + ",";
  json += "\"adaptThresh\":" + fnum(adaptive_temp_thresh, 2) + ",";
  json += "\"mq135\":" + String(mq135_raw) + ",";
  json += "\"mq2\":" + String(mq2_raw) + ",";
  json += "\"ldr\":" + String(ldr_raw) + ",";
  json += "\"vib\":" + fnum(vib_g, 3) + ",";
  json += "\"roll\":" + fnum(roll_deg, 1) + ",";
  json += "\"pitch\":" + fnum(pitch_deg, 1) + ",";
  json += "\"dist1\":" + fnum(dist1_cm, 1) + ",";
  json += "\"dist2\":" + fnum(dist2_cm, 1) + ",";
  // Expose the last unfiltered echo-derived values as diagnostics. The age and
  // EchoOk fields above indicate whether each raw reading is still fresh.
  // This is especially useful for distinguishing a real close return from a
  // filter/mount/wiring issue during ultrasonic commissioning.
  json += "\"us1RawCm\":" + fnum(us1_raw_cm, 2) + ",";
  json += "\"us2RawCm\":" + fnum(us2_raw_cm, 2) + ",";
  json += "\"u\":" + fnum(control_u, 3) + ",";
  json += "\"x1\":" + fnum(x1_real, 3) + ",";
  json += "\"x1_hat\":" + fnum(x1_hat, 3) + ",";
  json += "\"x2\":" + fnum(x2_real, 2) + ",";
  json += "\"x2_hat\":" + fnum(peak_x2_hat, 2) + ",";
  json += "\"y_twin\":" + fnum(y_twin, 3) + ",";
  json += "\"residual\":" + fnum(residual, 3) + ",";
  json += "\"cusum_sp\":" + fnum(cusum_twin.Splus(), 3) + ",";
  json += "\"cusum_sm\":" + fnum(cusum_twin.Sminus(), 3) + ",";
  json += "\"cusum_alarm\":" + String(cusum_twin.alarm() ? 1 : 0) + ",";
  json += "\"servo\":" + String(servo_angle) + ",";
  json += "\"servoUsChannel\":" + String(servo_us_channel) + ",";
  json += "\"alarm\":" + String(alarm_state) + ",";
  json += "\"reason\":\"" + jsonEscape(last_alarm_reason) + "\",";
  json += "\"muted\":" + String(buzzer_muted ? 1 : 0) + ",";
  json += "\"mode\":" + String(control_mode) + ",\"trackState\":" + String((int)track_state) + ",";
  json += "\"trackAngle\":" + fnum(track_state == TRACK_LOCKED ? track_locked_angle : track_sweep_angle, 1) + ",";
  json += "\"trackAngleIsCommanded\":1,";
  json += "\"trackBestCm\":" + fnum(track_best_cm, 1) + ",";
  json += "\"trackBroadReturn\":" + String(track_broad_return ? 1 : 0) + ",";
  json += "\"up\":" + String(millis() / 1000) + ",\"heap\":" + String(ESP.getFreeHeap()) + ",\"rssi\":" + String(WiFi.status() == WL_CONNECTED ? WiFi.RSSI() : 0) + ",";
  json += "\"gasOk\":" + String((web_manual_override || millis() > GAS_WARMUP_MS) ? 1 : 0) + ",\"stepOk\":" + String(step_valid ? 1 : 0) + ",";
  json += "\"tr\":" + fnum(meas_tr_ms, 0) + ",\"ts\":" + fnum(meas_ts_ms, 0) + ",\"os\":" + fnum(meas_os_pct, 1) + ",\"sse\":" + fnum(meas_sse_pct, 2);
  json += "}";
  return json;
}

// --------------------- Dedicated OLED Screen per Mode ---------------------
void updateOLEDDisplay()
{
  if (!oled_found)
    return;

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);

  switch (control_mode)
  {
  case 0:
  {
    // MODE 0: ALL SENSORS FLIGHT HUD (Dual Ultrasonic Real-Time Monitoring)
    display.println(">> ALL SENSORS HUD <<");
    display.printf("T:%.1fC H:%.0f%% V:%.2fg\n", temp_c, humidity, vib_g);
    display.printf("Rad:%.0fcm Alt:%.0fcm\n", getServoDist(), getBaseDist());
    display.printf("Gas:%d LDR:%d\n", mq135_raw, ldr_raw);
    String ipStr = (WiFi.status() == WL_CONNECTED) ? WiFi.localIP().toString() : WiFi.softAPIP().toString();
    display.printf("WiFi: %s\n", ipStr.c_str());
    display.println(alarm_state == 2 ? "[RED ALERT: HAZARD]" : (alarm_state == 1 ? "[YELLOW CAUTION]" : "[STATUS: NOMINAL GREEN]"));
    break;
  }

  case 1:
  {
    // MODE 1: RADAR PROXIMITY SCAN / TARGET SECTOR HOLD
    float sd = getServoDist();
    display.println(">> MODE 1: SERVO SCAN <<");
    display.printf("Status: %s\n", track_broad_return ? "WIDE REFLECTION" : (track_state == TRACK_LOCKED ? "LOCKED [SECTOR]" : (track_state == TRACK_REACQUIRE ? "REACQUIRE..." : "SEARCHING...")));
    display.printf("Target range: %.1f cm\n", sd);
    display.printf("Servo Pos: %d deg\n", servo_angle);
    if (sd < 14.0f)
      display.println(">> [RED] CLOSE <14cm");
    else if (sd < 28.0f)
      display.println(">> [YEL] TRACKING <28cm");
    else
      display.println(">> [GRN] NOMINAL >28cm");
    break;
  }

  case 2:
  {
    // MODE 2: RADAR SWEEP (180°)
    display.println(">> MODE 2: RADAR SWEEP <<");
    display.printf("Radar Angle: %d deg\n", sweep_angle);
    display.printf("Obstacle Dist: %.1f cm\n", dist2_cm);
    display.printf("Altitude Dist: %.1f cm\n", dist1_cm);
    display.printf("Sector Scan: 0..180\n");
    display.println(dist2_cm < 14.0f ? ">> OBSTACLE DETECTED <<" : "Air Corridor: CLEAR");
    break;
  }

  case 3:
  {
    // MODE 3: LQR + DIGITAL TWIN RESIDUAL & CUSUM (Araújo et al. 2025)
    display.println(">> MODE 3: LQR + TWIN <<");
    display.printf("x1_real: %.2f  Ang:%d\n", x1_real, servo_angle);
    display.printf("x1_hat:  %.2f (Obs)\n", x1_hat);
    display.printf("CUSUM S+:%.3f (h:0.06)\n", cusum_twin.Splus());
    display.printf("Residual:%.3f (d:0.10)\n", residual);
    display.println(cusum_twin.alarm() ? ">> CUSUM FAULT ALARM! <<" : "Digital Twin: HEALTHY");
    break;
  }

  case 4:
  {
    // MODE 4: STEP RESPONSE DYNAMIC BENCHMARK
    display.println(">> MODE 4: STEP TEST <<");
    display.printf("Target Angle: %d deg\n", step_toggle ? 153 : 27);
    display.printf("Current Servo: %d deg\n", servo_angle);
    if (step_valid)
    {
      display.printf("Tr(10-90): %.0f ms\n", meas_tr_ms);
      if (meas_ts_ms >= 2900.0f)
        display.println("Ts(2%): not settled");
      else
        display.printf("Ts(2%%):    %.0f ms\n", meas_ts_ms);
      display.printf("OS:%.1f%% SSE:%.1f%%\n", meas_os_pct, meas_sse_pct);
    }
    else
    {
      display.println("Measuring step...");
    }
    break;
  }

  case 5:
  {
    // MODE 5: IMU ATTITUDE GIMBAL
    display.println(">> MODE 5: IMU ATTITUDE <<");
    display.printf("Roll:  %+.1f deg\n", roll_deg);
    display.printf("Pitch: %+.1f deg\n", pitch_deg);
    display.printf("Vibration: %.2f g\n", vib_g);
    display.printf("Gimbal Servo: %d deg\n", servo_angle);
    display.println(vib_g > 0.25f ? ">> VIBRATION SHOCK! <<" : "Attitude: STABILIZED");
    break;
  }
  }
  display.display();
}

// ===================== SETUP: HARDWARE BOOT ===============================
void setup()
{
  Serial.begin(460800);
  Serial.setTimeout(20); // readStringUntil() must never stall the 20 Hz loop
  delay(250);

  analogSetAttenuation(ADC_11db);

  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_YELLOW, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  pinMode(PIN_TRIG1, OUTPUT);
  pinMode(PIN_ECHO1, INPUT_PULLDOWN); // quiet disconnected/noisy echo line
  pinMode(PIN_TRIG2, OUTPUT);
  pinMode(PIN_ECHO2, INPUT_PULLDOWN); // quiet disconnected/noisy echo line

  // Button pins
  pinMode(PIN_BTN_BOOT, INPUT_PULLUP);
  pinMode(PIN_BTN_EXT, INPUT_PULLUP);
  pinMode(PIN_BTN_SVN, INPUT);

  // Default to GREEN LED immediately
  digitalWrite(PIN_LED_RED, LOW);
  digitalWrite(PIN_LED_YELLOW, LOW);
  digitalWrite(PIN_LED_GREEN, HIGH);

  // Initialize SG90 Servo
  ESP32PWM::allocateTimer(0);
  damperServo.setPeriodHertz(50);
  damperServo.attach(PIN_SERVO, 500, 2400);

  // Boot sweep
  damperServo.write(0);
  delay(180);
  damperServo.write(180);
  delay(180);
  damperServo.write(90);
  delay(180);

  // Friendly boot chime (soft, gentle confirmation)
  digitalWrite(PIN_BUZZER, HIGH);
  delay(25);
  digitalWrite(PIN_BUZZER, LOW);
  delay(40);
  digitalWrite(PIN_BUZZER, HIGH);
  delay(35);
  digitalWrite(PIN_BUZZER, LOW);

  dht.begin();
  Wire.begin(I2C_SDA, I2C_SCL);

  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x6B);
  Wire.write(0x00);
  mpu_found = (Wire.endTransmission() == 0);
  if (mpu_found)
  {
    Wire.beginTransmission(MPU_ADDR);
    Wire.write(0x1A); // CONFIG: digital low-pass filter ~94 Hz
    Wire.write(0x02);
    Wire.endTransmission();
  }

  if (display.begin(SSD1306_SWITCHCAPVCC, 0x3C))
  {
    oled_found = true;
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(0, 0);
    display.println("UAV AVIONICS TESTBED");
    display.println("Manav Sharma 24BEC0566");
    display.println("--------------------");
    display.println("Status: ONLINE [OK]");
    display.display();
  }
  Serial.printf("[SENSOR] MPU6050=%s OLED=%s DHT11=awaiting first read\n", mpu_found ? "OK" : "MISSING", oled_found ? "OK" : "MISSING");

  enableLoopWDT(); // reboot instead of hanging if loop stalls

  // Dual AP + STA Mode: Guaranteed wireless access anywhere
  WiFi.mode(WIFI_AP_STA);
  WiFi.setTxPower(WIFI_POWER_19_5dBm);
  WiFi.persistent(false);

  // Disable Wi-Fi modem sleep to lock radio active: eliminates 50-100ms jitter spikes, drops ping to 1-2 ms
  WiFi.setSleep(false);
  esp_wifi_set_ps(WIFI_PS_NONE);

  // 1. Activate Dedicated Access Point (Open: 192.168.4.1, Channel 6)
  IPAddress apIP(192, 168, 4, 1);
  IPAddress apGW(192, 168, 4, 1);
  IPAddress apSub(255, 255, 255, 0);
  WiFi.softAPConfig(apIP, apGW, apSub);
  WiFi.softAP("AeroLab-Avionics", "", 6, 0, 4); // Ch 6, Open network, Max 4 clients
  delay(80);
  Serial.print("[WIFI AP] AeroLab-Avionics HOTSPOT ONLINE | Static IP: ");
  Serial.println(WiFi.softAPIP());

  // 2. Also check background station if available
  if (strlen(WIFI_SSID) > 0)
  {
    Serial.printf("[WIFI STA] Checking background hotspot: %s...\n", WIFI_SSID);
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    unsigned long startWifi = millis();
    while (WiFi.status() != WL_CONNECTED && millis() - startWifi < 2500)
    {
      delay(100);
    }
    if (WiFi.status() == WL_CONNECTED)
    {
      Serial.print("[WIFI STA] Connected! Station IP: ");
      Serial.println(WiFi.localIP());
      WiFi.setAutoReconnect(true);
    }
    else
    {
      // If STA not found, stop scanning so background channel hops do NOT interfere with AP channel
      WiFi.disconnect(false);
      WiFi.setAutoReconnect(false);
      Serial.println("[WIFI AP] Hotspot standalone mode active on Channel 6. Static IP: 192.168.4.1");
    }
  }

  // 3. mDNS discovery
  if (MDNS.begin("aerolab"))
  {
    MDNS.addService("http", "tcp", 80);
    Serial.println("[mDNS] http://aerolab.local active");
  }

  // 4. ArduinoOTA wireless flashing
  ArduinoOTA.setHostname("aerolab");
  ArduinoOTA.onStart([]() { damperServo.write(90); });
  ArduinoOTA.begin();
  net_up = true;

  // 5. Web Server Endpoints (Ultra-Low Latency SSE + JSON API + Mini HUD)
  server.on("/", HTTP_GET, []() {
    server.sendHeader("Access-Control-Allow-Origin", "*");
    server.send_P(200, "text/html", MINI_HUD_HTML);
  });
  // /events endpoint retired in favor of high-throughput 20 Hz /telemetry
  server.on("/telemetry", HTTP_GET, []() {
    server.sendHeader("Access-Control-Allow-Origin", "*");
    server.sendHeader("Access-Control-Allow-Headers", "*");
    server.send(200, "application/json", getTelemetryJSON());
  });
  server.on("/cmd", HTTP_GET, []() {
    server.sendHeader("Access-Control-Allow-Origin", "*");
    server.sendHeader("Access-Control-Allow-Headers", "*");
    if (server.hasArg("c")) processWebCommand(server.arg("c"));
    server.send(200, "text/plain", "OK");
  });
  server.on("/cmd", HTTP_OPTIONS, []() {
    server.sendHeader("Access-Control-Allow-Origin", "*");
    server.sendHeader("Access-Control-Allow-Methods", "GET,POST,OPTIONS");
    server.sendHeader("Access-Control-Allow-Headers", "*");
    server.send(204);
  });
  server.begin();
  Serial.println("[HTTP] WebServer active on port 80");
}

// ===================== MAIN CONTROL LOOP ==================================
void loop()
{
  feedLoopWDT();
  if (net_up)
    ArduinoOTA.handle();

  // Non-blocking active buzzer auto-shutoff (zero CPU blocking)
  if (buzzer_off_ms > 0 && millis() >= buzzer_off_ms)
  {
    digitalWrite(PIN_BUZZER, LOW);
    buzzer_off_ms = 0;
  }

  // 0. CHECK PHYSICAL HARDWARE BUTTONS
  checkHardwareButtons();

  while (Serial.available())
  {
    String cmd = Serial.readStringUntil('\n');
    processWebCommand(cmd);
  }
  server.handleClient();

  unsigned long now = millis();

  // 1. FAST STATE-SPACE CONTROL & ULTRASONIC LOOP (20 Hz / 50 ms)
  if (now - lastControlMs >= 50)
  {
    float dt = (now - lastControlMs) / 1000.0f;
    lastControlMs = now;

    ldr_raw = avgAnalog(PIN_LDR);
    mq135_raw = avgAnalog(PIN_MQ135);
    mq2_raw = avgAnalog(PIN_MQ2);
    readMPUMotion();
    bool us1_new_sample = false;
    bool us2_new_sample = false;

    if (web_manual_override)
    {
      mq135_raw = man_gas;
      ldr_raw = man_ldr;
      vib_g = man_vib;
      dist1_cm = man_dist1;
      dist2_cm = 60.0f;
      us1_echo_ok = false;
      us2_echo_ok = false;
      us1_diag = us2_diag = 4;
      us1_pulse_us = us2_pulse_us = 0;
      dht_ok = false;
    }
    else
    {
      // Sample both sensors at the 20 Hz control tick; never feed timeout sentinels
      // into the EMA range filter. A fresh valid range is required for tracking/alarms.
      const UltrasonicReading sample1 = readUltrasonicCM(PIN_TRIG1, PIN_ECHO1, 12000);
      const float raw1 = sample1.cm;
      us1_pulse_us = sample1.pulse_us;
      us1_diag = sample1.diagnostic;
      const bool us1_raw_ok = sample1.diagnostic == 1;
      if (us1_raw_ok)
      {
        us1_new_sample = true;
        const bool us1_had_valid = us1_seen_valid;
        us1_last_valid_ms = now;
        us1_seen_valid = true;
        us1_raw_cm = raw1;
        filt_dist1 = us1_had_valid && filt_dist1 >= ULTRASONIC_MIN_RELIABLE_CM && filt_dist1 <= ULTRASONIC_MAX_RELIABLE_CM
                         ? 0.65f * raw1 + 0.35f * filt_dist1 : raw1;
        dist1_cm = filt_dist1;
      }
      else if (!us1_seen_valid || now - us1_last_valid_ms > 300)
        dist1_cm = 999.0f; // distinct no-range sentinel, never confused with a 120 cm echo
      us1_echo_ok = us1_seen_valid && now - us1_last_valid_ms <= 300;

      // Let the first sensor's complete echo window finish before triggering
      // the second. A 2.5 ms gap allowed late US1 echoes (up to 12 ms) to be
      // mistaken for very short US2 returns and cause false proximity alarms.
      delayMicroseconds(15000);
      const UltrasonicReading sample2 = readUltrasonicCM(PIN_TRIG2, PIN_ECHO2, 12000);
      const float raw2 = sample2.cm;
      us2_pulse_us = sample2.pulse_us;
      us2_diag = sample2.diagnostic;
      const bool us2_raw_ok = sample2.diagnostic == 1;
      if (us2_raw_ok)
      {
        us2_new_sample = true;
        const bool us2_had_valid = us2_seen_valid;
        us2_last_valid_ms = now;
        us2_seen_valid = true;
        us2_raw_cm = raw2;
        filt_dist2 = us2_had_valid && filt_dist2 >= ULTRASONIC_MIN_RELIABLE_CM && filt_dist2 <= ULTRASONIC_MAX_RELIABLE_CM
                         ? 0.65f * raw2 + 0.35f * filt_dist2 : raw2;
        dist2_cm = filt_dist2;
      }
      else if (!us2_seen_valid || now - us2_last_valid_ms > 300)
        dist2_cm = 999.0f;
      us2_echo_ok = us2_seen_valid && now - us2_last_valid_ms <= 300;
    }

    if (radar1_until > now)
      dist1_cm = 8.0f;
    if (tripwire_until > now)
      dist2_cm = 9.0f;
    if (boost_gas > 0)
      mq135_raw = constrain(mq135_raw + boost_gas, 0, 4095);
    if (abs(boost_ldr) > 10)
      ldr_raw = constrain(ldr_raw + boost_ldr, 0, 4095);
    if (boost_vib > 0.01f)
      vib_g += boost_vib;

    // --- ACCURATE SENSITIVE PROXIMITY DETECTION (ALL MODES) ---
    const bool us1_fresh = us1_echo_ok && us1_seen_valid && now - us1_last_valid_ms <= 300;
    const bool us2_fresh = us2_echo_ok && us2_seen_valid && now - us2_last_valid_ms <= 300;
    bool u1_valid = us1_fresh && dist1_cm >= ULTRASONIC_MIN_RELIABLE_CM && dist1_cm < 42.0f;
    bool u2_valid = us2_fresh && dist2_cm >= ULTRASONIC_MIN_RELIABLE_CM && dist2_cm < 42.0f;
    const bool range_unknown = !us1_fresh || !us2_fresh;

    bool u1_critical = (u1_valid && dist1_cm < 14.0f);
    bool u2_critical = (u2_valid && dist2_cm < 14.0f);
    bool u1_caution  = (u1_valid && dist1_cm >= 14.0f && dist1_cm < 28.0f);
    bool u2_caution  = (u2_valid && dist2_cm >= 14.0f && dist2_cm < 28.0f);

    // Confirm on distinct fresh echo samples, not repeated loop reads of one
    // cached measurement. A missing/invalid echo breaks the confirmation run.
    us1_critical_ticks = gnc::freshConfirmationCount(us1_new_sample, u1_critical, us1_critical_ticks, 2);
    us2_critical_ticks = gnc::freshConfirmationCount(us2_new_sample, u2_critical, us2_critical_ticks, 2);
    us1_caution_ticks = gnc::freshConfirmationCount(us1_new_sample, u1_caution, us1_caution_ticks, 2);
    us2_caution_ticks = gnc::freshConfirmationCount(us2_new_sample, u2_caution, us2_caution_ticks, 2);
    const bool u1_critical_confirmed = us1_critical_ticks >= 2;
    const bool u2_critical_confirmed = us2_critical_ticks >= 2;
    const bool u1_caution_confirmed = us1_caution_ticks >= 2;
    const bool u2_caution_confirmed = us2_caution_ticks >= 2;
    near_dist = (u1_critical_confirmed || u2_critical_confirmed);
    caution_dist = (u1_caution_confirmed || u2_caution_confirmed);

    bool trip_temp = (temp_c >= adaptive_temp_thresh);
    const bool gas_ok = web_manual_override || now > GAS_WARMUP_MS;
    bool trip_gas = gas_ok && (mq135_raw > 3200);
    // Photocell divider polarity/thresholds are installation-dependent; until
    // calibrated in the mounted lighting conditions, report raw ADC only.
    bool trip_residual = ((control_mode == 3 || fault_drift_injected) && (residual > 0.100f || cusum_twin.alarm()));

    const String held_reason = last_alarm_reason;
    if (near_dist)
    {
      if (u1_critical_confirmed && u2_critical_confirmed)
        last_alarm_reason = "CRITICAL PROXIMITY (<14cm): Both Sensors! (U1=" + String(dist1_cm, 1) + "cm, U2=" + String(dist2_cm, 1) + "cm)";
      else if (u2_critical_confirmed)
        last_alarm_reason = "CRITICAL PROXIMITY (<14cm): Servo Radar (US2)=" + String(dist2_cm, 1) + "cm";
      else
        last_alarm_reason = "CRITICAL PROXIMITY (<14cm): Fixed Sensor (US1)=" + String(dist1_cm, 1) + "cm";
    }
    else if (trip_temp)
    {
      last_alarm_reason = "HIGH TEMP: " + String(temp_c, 1) + "C >= " + String(adaptive_temp_thresh, 1) + "C Limit";
    }
    else if (trip_gas)
    {
      last_alarm_reason = "GAS HAZARD: MQ-135=" + String(mq135_raw) + " (>3200 Limit)";
    }
    else if (trip_residual)
    {
      last_alarm_reason = "TWIN DRIFT: Res=" + String(residual, 3) + " (S+=" + String(cusum_twin.Splus(), 3) + ")";
    }
    else if (caution_dist)
    {
      if (u1_caution_confirmed && u2_caution_confirmed)
        last_alarm_reason = "CAUTION: Obstacle in 28cm range (Both Sensors)";
      else if (u2_caution_confirmed)
        last_alarm_reason = "CAUTION: Obstacle in 28cm range (Servo Radar US2=" + String(dist2_cm, 1) + "cm)";
      else
        last_alarm_reason = "CAUTION: Obstacle in 28cm range (Fixed Sensor US1=" + String(dist1_cm, 1) + "cm)";
    }
    else if (gas_ok && mq135_raw > 2400)
    {
      last_alarm_reason = "CAUTION: Gas elevated (MQ-135=" + String(mq135_raw) + ")";
    }
    else if (vib_g > 0.40f)
    {
      last_alarm_reason = "CAUTION: IMU Vibration Shock (" + String(vib_g, 2) + "g)";
    }
    else if (range_unknown)
    {
      last_alarm_reason = String("RANGE UNKNOWN: US1 ") + (us1_fresh ? "FRESH" : "NO FRESH ECHO") +
                          ", US2 " + (us2_fresh ? "FRESH" : "NO FRESH ECHO");
    }
    else
    {
      last_alarm_reason = "SYSTEM NOMINAL [GREEN]";
    }

    // Alarm Hysteresis: escalate immediately, de-escalate only after 10 clean ticks (0.5 s)
    const int raw_alarm = (near_dist || trip_temp || trip_gas || trip_residual) ? 2
                          : ((caution_dist || (gas_ok && mq135_raw > 2400) || vib_g > 0.40f || range_unknown) ? 1 : 0);
    static uint8_t clear_ticks = 0;
    const int effective_alarm = raw_alarm;
    if (effective_alarm >= alarm_state)
    {
      alarm_state = effective_alarm;
      clear_ticks = 0;
    }
    else if (++clear_ticks >= 10)
    {
      alarm_state = effective_alarm;
      clear_ticks = 0;
    }
    else
    {
      last_alarm_reason = held_reason;
    }

    digitalWrite(PIN_LED_RED, alarm_state == 2);
    digitalWrite(PIN_LED_YELLOW, alarm_state == 1);
    digitalWrite(PIN_LED_GREEN, alarm_state == 0);

    if (test_start_ms)
    {
      digitalWrite(PIN_LED_RED, HIGH);
      digitalWrite(PIN_LED_YELLOW, HIGH);
      digitalWrite(PIN_LED_GREEN, LOW);
    }

    float setpoint_r = 0.5f; // Neutral 90 degrees

    if (man_servo >= 0)
    {
      setpoint_r = man_servo / 180.0f;
    }
    else
    {
      switch (control_mode)
      {
      case 0:
      {
        // MODE 0: ALL-IN-ONE FLIGHT HUD
        setpoint_r = 0.50f;
        break;
      }

      case 1:
      {
        // MODE 1: full commanded-sector scan/hold/reacquire. One range sensor
        // cannot classify a human or provide continuous lateral hand pose.
        float sd = getServoDist();
        const bool servo_sensor_valid = servo_us_channel == 1
            ? (us1_echo_ok && us1_seen_valid && now - us1_last_valid_ms <= 300)
            : (us2_echo_ok && us2_seen_valid && now - us2_last_valid_ms <= 300);
        const bool servo_sensor_new_sample = servo_us_channel == 1 ? us1_new_sample : us2_new_sample;
        // Empty-room returns on this rig are typically 60-70 cm. Restrict
        // acquisition so distant walls are not mistaken for the user's hand.
        const bool has_target = gnc::freshRangeTarget(servo_sensor_valid, servo_sensor_new_sample,
                                                      sd, ULTRASONIC_MIN_RELIABLE_CM, HAND_SCAN_MAX_CM);

        if (track_state == TRACK_SEARCHING)
        {
          if (now >= track_next_sample_ms)
          {
            // servo_angle is the last commanded PWM position, not encoder feedback.
            const bool servo_at_scan_sector = abs(servo_angle - (int)lroundf(track_sweep_angle)) <= 5;
            if (!servo_at_scan_sector)
            {
              // Let the servo reach its commanded sector before advancing.
              track_next_sample_ms = now + 30;
            }
            else
            {
              // Missing echoes do not stop the mechanical search; they simply
              // cannot contribute evidence toward a target or a lock.
              if (servo_sensor_new_sample)
              {
                const int scan_bin = gnc::rangeScanBin((float)servo_angle);
                const uint32_t scan_bit = scan_bin >= 0 ? (1UL << scan_bin) : 0;
                track_sample_mask |= scan_bit;
                if (has_target)
                {
                  track_target_mask |= scan_bit;
                  if (sd < track_best_cm)
                  {
                    track_best_cm = sd;
                    track_best_angle = (float)servo_angle;
                  }
                }
              }
              const bool full_sweep_complete = (track_sweep_dir > 0.0f && track_sweep_angle >= 145.0f) ||
                                               (track_sweep_dir < 0.0f && track_sweep_angle <= 35.0f);
              if (full_sweep_complete)
              {
                track_broad_return = gnc::broadRangeScan(track_sample_mask, track_target_mask);
                if (gnc::rangeScanCanLock(track_sample_mask, track_target_mask, true))
                {
                  track_locked_angle = track_best_angle;
                  track_state = TRACK_LOCKED;
                  playTone(1300, 25);
                }
                track_best_cm = 150.0f;
                track_sample_mask = track_target_mask = 0;
                if (track_state == TRACK_LOCKED)
                  track_sweep_angle = track_locked_angle;
                else
                {
                  track_sweep_dir = -track_sweep_dir;
                  track_sweep_angle = constrain(track_sweep_angle + track_sweep_dir * 6.0f, 35.0f, 145.0f);
                }
              }
              else track_sweep_angle = constrain(track_sweep_angle + track_sweep_dir * 6.0f, 35.0f, 145.0f);
              track_next_sample_ms = now + 80;
            }
          }
          setpoint_r = track_sweep_angle / 180.0f;
        }
        else if (track_state == TRACK_LOCKED)
        {
          if (has_target)
          {
            track_next_sample_ms = now + 180;
            setpoint_r = track_locked_angle / 180.0f;
          }
          else
          {
            if (now >= track_next_sample_ms)
            {
              track_state = TRACK_REACQUIRE;
              track_sweep_angle = track_locked_angle;
              track_sweep_dir = 1.0f;
              track_next_sample_ms = now;
            }
            else setpoint_r = track_locked_angle / 180.0f;
          }
        }
        else if (track_state == TRACK_REACQUIRE)
        {
          // Reacquisition must earn a new lock through a complete coverage scan;
          // one reappearing echo cannot immediately relock a sector.
          track_state = TRACK_SEARCHING;
          track_sweep_angle = 35.0f;
          track_sweep_dir = 1.0f;
          track_sample_mask = track_target_mask = 0;
          track_best_cm = 150.0f;
          track_broad_return = false;
          track_next_sample_ms = now;
          setpoint_r = track_sweep_angle / 180.0f;
        }

        break;
      }

      case 2:
      {
        // MODE 2: 180° RADAR SWEEP (Ultrasonic on Servo)
        if (now - last_sweep_ms >= 35)
        {
          last_sweep_ms = now;
          sweep_angle += sweep_dir;
          if (sweep_angle >= 165)
          {
            sweep_angle = 165;
            sweep_dir = -3;
          }
          if (sweep_angle <= 15)
          {
            sweep_angle = 15;
            sweep_dir = 3;
          }
        }
        setpoint_r = sweep_angle / 180.0f;
        break;
      }

      case 3:
      {
        // MODE 3: LQR OPTIMAL CLOSED-LOOP DAMPER & DIGITAL TWIN
        float temp_demand = constrain((temp_c - 27.0f) / (adaptive_temp_thresh - 27.0f), 0.0f, 1.0f);
        float gas_demand = constrain((mq135_raw - 1200.0f) / 1800.0f, 0.0f, 1.0f);
        setpoint_r = max(temp_demand, gas_demand);
        if (alarm_state == 2)
          setpoint_r = 1.0f;
        break;
      }

      case 4:
      {
        // MODE 4: DYNAMIC STEP-RESPONSE BENCHMARK
        if (now - last_step_ms >= 3000)
        {
          last_step_ms = now;
          step_toggle = !step_toggle;
          beginStepMeasure(x1_real, step_toggle ? 0.85f : 0.15f);
        }
        setpoint_r = step_toggle ? 0.85f : 0.15f; // Jumps between ~27° and ~153°
        break;
      }

      case 5:
      {
        // MODE 5: IMU ATTITUDE GIMBAL STABILIZATION
        float target_angle = 90.0f - (roll_deg * 1.2f);
        setpoint_r = constrain(target_angle / 180.0f, 0.0f, 1.0f);
        break;
      }
      }
    }

    // Non-blocking TEST_ALARM sequence sweeps servo smoothly inside the loop
    if (test_start_ms)
    {
      unsigned long e = now - test_start_ms;
      if (e < 400)
        setpoint_r = 1.0f;
      else if (e < 800)
        setpoint_r = 0.0f;
      else if (e < 1200)
        setpoint_r = 0.5f;
      else
      {
        test_start_ms = 0;
        Serial.println("[CMD_ACK] TEST_ALARM_DONE");
      }
    }

    stepControlAndObserver(setpoint_r, dt);
  }

  // 2. ULTRA-FAST TELEMETRY BROADCAST (20 Hz / 50 ms synchronized with discrete LQR loop)
  if (now - lastTelemetryMs >= 50)
  {
    lastTelemetryMs = now;
    Serial.println(getTelemetryJSON());
    peak_x2_hat *= 0.25f;
  }

  // 3. SLOW ENVIRONMENTAL SENSORS & DHT11 (2 Hz / 500 ms)
  if (now - lastSlowMs >= 500)
  {
    float dt_slow = (now - lastSlowMs) / 1000.0f;
    lastSlowMs = now;

    float base_t = temp_c;
    if (web_manual_override)
    {
      base_t = man_temp;
    }
    else
    {
      float t = dht.readTemperature();
      float h = dht.readHumidity();
      const bool temp_valid = !isnan(t) && t > 0.0f && t < 70.0f;
      const bool humidity_valid = !isnan(h) && h > 0.0f && h <= 100.0f;
      dht_ok = temp_valid && humidity_valid;
      if (temp_valid)
        base_t = t;
      if (humidity_valid)
        humidity = h;
    }

    float new_temp = base_t + boost_temp;
    temp_rate = (new_temp - prev_temp) / dt_slow;
    prev_temp = new_temp;
    temp_c = new_temp;

    if (boost_temp > 0.05f)
      boost_temp *= 0.80f;
    else
      boost_temp = 0.0f;
    if (boost_gas > 20)
      boost_gas = (int)(boost_gas * 0.75f);
    else
      boost_gas = 0;
    if (abs(boost_ldr) > 20)
      boost_ldr = (int)(boost_ldr * 0.75f);
    else
      boost_ldr = 0;
    if (boost_vib > 0.02f)
      boost_vib *= 0.65f;
    else
      boost_vib = 0.0f;

    float rapid_rise_penalty = max(0.0f, temp_rate * 4.5f);
    adaptive_temp_thresh = constrain(base_temp_thresh - rapid_rise_penalty, 38.0f, 50.0f);

    if (!net_up && WiFi.status() == WL_CONNECTED)
    {
      net_up = true;
      Serial.print("[WIFI] connected, http://");
      Serial.println(WiFi.localIP());
      if (MDNS.begin("aerolab"))
        MDNS.addService("http", "tcp", 80);
      ArduinoOTA.setHostname("aerolab");
      ArduinoOTA.onStart([]()
                         { damperServo.write(90); });
      ArduinoOTA.begin();
      Serial.println("[NET] http://aerolab.local  |  OTA ready (env:ota)");
    }

    // Refresh OLED
    updateOLEDDisplay();
  }

  // 4. ACTIVE PROXIMITY BUZZER SOUNDER (Gentle, Whisper-Quiet Sound Levels)
  static unsigned long last_buzzer_beep_ms = 0;
  if (!buzzer_muted)
  {
    if (alarm_state == 2)
    {
      // Critical Red Alarm: clear, crisp, audible alert beep on red light!
      if (now - last_buzzer_beep_ms >= 550)
      {
        last_buzzer_beep_ms = now;
        triggerBuzzer(25); // Audible 25ms alert beep
      }
    }
    else if (alarm_state == 1 && caution_dist && !prox_alarm_muted)
    {
      // Caution Yellow: soft subtle pip every 1800ms
      if (now - last_buzzer_beep_ms >= 1800)
      {
        last_buzzer_beep_ms = now;
        triggerBuzzer(6); // 6ms soft tick
      }
    }
  }
  else
  {
    digitalWrite(PIN_BUZZER, LOW);
  }
}
